#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Re-implementation of the original binary's behaviour.
 * If called with no argument or with an empty argument it prints:
 *      EMPTY
 * otherwise it prints the Soundex code of the first argument.
 * The implementation follows the classic Soundex rules.
 */

static int soundex_digit(char ch)
{
    switch (ch) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

static void compute_soundex(const char *word, char out[5])
{
    out[0] = (char)toupper((unsigned char)word[0]);
    int prev_digit = soundex_digit(out[0]);
    int idx = 1;
    for (size_t i = 1; word[i] != '\0' && idx < 4; ++i) {
        char ch = (char)toupper((unsigned char)word[i]);
        int d = soundex_digit(ch);
        if (d == 0) continue;          // ignore vowels and non‑coded letters
        if (d == prev_digit) continue; // suppress duplicate codes
        out[idx++] = (char)('0' + d);
        prev_digit = d;
    }
    while (idx < 4) out[idx++] = '0';
    out[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }
    char result[5];
    compute_soundex(argv[1], result);
    puts(result);
    return 0;
}
